<!-- SPDX-License-Identifier: MPL-2.0 -->
<template>
 <section class="catalog">
  <div class="row q-col-gutter-sm q-my-sm"><q-select class="col-12 col-sm-4" dark outlined v-model="provider" :options="providers" label="下载来源" :disable="busy" @update:model-value="reset"/><q-input class="col" dark outlined v-model="query" label="搜索名称" @keyup.enter="search(0)"/><q-btn class="q-ml-sm" color="primary" label="搜索" :disable="busy" @click="search(0)"/></div>
  <div v-if="packs && provider==='atlauncher'" class="row q-gutter-sm q-mb-md"><q-input class="col" dark outlined v-model="shareCode" label="ATLauncher 分享码"/><q-btn label="解析分享码" :disable="busy || !shareCode" @click="resolveShare"/></div>
  <div v-if="packs && provider==='ftb'" class="row q-gutter-sm q-mb-md"><q-input class="col" dark outlined v-model="ftbPath" label="FTB App 实例目录"/><q-btn label="读取本地实例" :disable="busy" @click="loadFtbLocal"/></div>
  <div v-if="packs && provider==='legacy-ftb'" class="row q-gutter-sm q-mb-md"><q-input class="col" dark outlined v-model="privateCode" label="Legacy FTB 私有代码"/><q-btn label="保存私有代码" :disable="busy || !privateCode" @click="savePrivateCode"/></div>
  <div v-if="!packs" class="row q-col-gutter-sm q-mb-md"><q-input class="col" dark outlined v-model="gameVersion" label="Minecraft 版本筛选"/><q-select class="col" dark outlined v-model="loader" :options="['','forge','fabric','neoforge','quilt','liteloader']" label="加载器筛选"/></div>
  <q-linear-progress v-if="busy" indeterminate/>
  <q-banner v-if="error" class="bg-red-9 q-my-sm">{{ error }}</q-banner>
  <template v-if="project">
   <q-btn flat icon="arrow_back" label="返回搜索结果" :disable="busy" @click="project=null"/><div class="catalog-project-hero"><q-avatar size="88px" rounded><img v-if="project.iconUrl" :src="project.iconUrl" :alt="project.name"/><q-icon v-else name="extension" size="42px" color="primary"/></q-avatar><div><div class="catalog-provider">{{ provider }}<span v-if="project.side"> · {{ project.side }}</span></div><h6>{{ project.name }}</h6><div class="catalog-project-id">{{ project.projectId }}</div></div></div><p class="catalog-description">{{ project.description }}</p><div v-if="project.authors?.length" class="catalog-authors">作者：{{ project.authors.map((author:any)=>author.name).filter(Boolean).join('、') }}</div><div v-if="project.body" class="catalog-body">{{ project.body }}</div><div class="row q-gutter-sm q-mb-md"><q-btn v-if="project.websiteUrl" flat icon="language" label="项目主页" @click="openExternal(project.websiteUrl)"/><q-btn v-if="project.sourceUrl" flat icon="code" label="源代码" @click="openExternal(project.sourceUrl)"/><q-btn v-if="project.issuesUrl" flat icon="bug_report" label="问题反馈" @click="openExternal(project.issuesUrl)"/></div>
   <q-input v-if="packs" dark outlined v-model="instanceName" label="新实例名称" class="q-mb-md"/>
   <q-select dark outlined v-model="version" :options="versions.map(v=>({label:versionLabel(v),value:v.versionId}))" emit-value map-options label="选择版本"/>
   <q-checkbox v-if="!packs" dark v-model="optional" label="同时安装可选依赖"/>
   <q-btn class="q-mt-md" color="primary" label="安装所选版本" :disable="busy || !version || (packs && !instanceName.trim())" @click="install"/>
  </template>
  <template v-else><q-list separator><q-item v-for="item in results" :key="item.projectId" clickable :disable="busy" @click="select(item)"><q-item-section avatar><q-avatar rounded size="46px" class="catalog-result-icon"><img v-if="item.iconUrl" :src="item.iconUrl" :alt="item.name"/><q-icon v-else name="extension" size="25px" color="primary"/></q-avatar></q-item-section><q-item-section><q-item-label>{{ item.name }}</q-item-label><q-item-label caption class="text-grey-5">{{ item.description }}</q-item-label><q-item-label caption class="catalog-result-meta">{{ item.provider || provider }} · {{ item.projectId }}</q-item-label></q-item-section><q-item-section side><q-icon name="chevron_right"/></q-item-section></q-item></q-list>
   <p v-if="searched && !results.length && !busy">没有找到符合条件的项目。</p>
   <div v-if="searched && ['modrinth','curseforge'].includes(provider)" class="row justify-between q-mt-md"><q-btn flat label="上一页" :disable="busy || offset===0" @click="search(Math.max(0,offset-25))"/><q-btn flat label="下一页" :disable="busy || !results.length" @click="search(offset+25)"/></div>
  </template>
 </section>
</template>
<script setup lang="ts">
import { ref, watch, computed } from 'vue';
const props=defineProps<{packs?:boolean;instance?:string;kind?:string;minecraftVersion?:string;busy:boolean;execute:(op:string,p:Record<string,unknown>)=>Promise<any>;defaultProvider?:string}>();
const emit=defineEmits<{installed:[]}>();
const providers=computed(()=>props.packs?['modrinth','curseforge','atlauncher','ftb','technic','legacy-ftb']:['modrinth','curseforge']);
const provider=ref(props.defaultProvider||'modrinth'),query=ref(''),results=ref<any[]>([]),project=ref<any>(null),versions=ref<any[]>([]),version=ref(''),error=ref(''),gameVersion=ref(props.minecraftVersion||''),loader=ref(''),instanceName=ref(''),optional=ref(false),offset=ref(0),searched=ref(false),shareCode=ref(''),ftbPath=ref(''),privateCode=ref('');
watch(()=>[props.instance,props.kind,props.packs],reset);watch(()=>props.defaultProvider,v=>{if(v){provider.value=v;reset();}});
function reset(){results.value=[];project.value=null;versions.value=[];version.value='';searched.value=false;error.value='';gameVersion.value=props.minecraftVersion||'';}
function imageUrl(value:any, id:string){const raw=value?.raw||{};const candidate=value?.iconUrl||value?.icon||value?.logoUrl||value?.logo?.url||value?.logo||raw.iconUrl||raw.logoUrl||raw.logo?.url||raw.logo||raw.icon?.url||raw.icon; if(typeof candidate==='string'&&candidate.trim())return candidate;return provider.value==='modrinth'&&id?`https://cdn.modrinth.com/data/${encodeURIComponent(id)}/icon.png`:'';}
function normalize(value:any){const id=String(value?.projectId||value?.slug||value?.id||'');return {...value,projectId:id,provider:provider.value,name:value.displayName||value.name||value.title||id,description:value.description||value.synopsis||value.summary||'',iconUrl:imageUrl(value,id)};}
function versionLabel(value:any){const game=Array.isArray(value.minecraftVersions)?value.minecraftVersions.slice(0,2).join(', '):(value.minecraftVersion||'');return `${value.name||value.version||value.versionId}${game?` · ${game}`:''}`;}
function params(){const p:Record<string,unknown>={provider:provider.value};if(!props.packs){p.kind=props.kind||'mods';if(gameVersion.value)p.minecraftVersion=gameVersion.value;if(loader.value)p.loaders=[loader.value];}return p;}
async function search(start:number){if(props.busy)return;error.value='';project.value=null;try{const r=await props.execute(props.packs?'modpack.search':'resource.search',{...params(),query:query.value,offset:start});const list=Array.isArray(r)?r:(r.results||r.projects||r.modpacks||[]);results.value=list.map(normalize);offset.value=start;searched.value=true;}catch(e){error.value=String(e);}}
async function select(item:any){if(props.busy)return;error.value='';project.value=normalize(item);versions.value=[];version.value='';instanceName.value=item.name;try{const detail=await props.execute(props.packs?'modpack.project':'resource.project',{...params(),projectId:item.projectId});project.value={...project.value,...normalize(detail)};const r=await props.execute(props.packs?'modpack.versions':'resource.versions',{...params(),projectId:item.projectId});versions.value=Array.isArray(r)?r:(r.versions||[]);}catch(e){error.value=String(e);}}
async function install(){if(props.busy)return;error.value='';try{await props.execute(props.packs?'modpack.install':'resource.install-with-dependencies',{...params(),projectId:project.value.projectId,versionId:version.value,...(props.packs?{name:instanceName.value}:{instance:props.instance,includeOptional:optional.value})});emit('installed');}catch(e){error.value=String(e);}}
async function resolveShare(){if(!shareCode.value)return;error.value='';try{const r=await props.execute('modpack.atlauncher.share-code',{code:shareCode.value});results.value=(r.packs||r.results||[r]).map(normalize);searched.value=true;}catch(e){error.value=String(e);}}
async function loadFtbLocal(){error.value='';try{const r=await props.execute('modpack.ftb-local.list',{path:ftbPath.value});results.value=(r.instances||r||[]).map(normalize);searched.value=true;}catch(e){error.value=String(e);}}
async function savePrivateCode(){error.value='';try{await props.execute('modpack.legacy-ftb.private-codes',{codes:[privateCode.value]});error.value='已保存 Legacy FTB 私有代码';}catch(e){error.value=String(e);}}
async function openExternal(url:string){try{await props.execute('desktop.open-url',{url});}catch{window.open(url,'_blank','noopener,noreferrer');}}
</script>
<style scoped>.catalog-project-hero{display:flex;align-items:center;gap:16px;margin:18px 0 10px}.catalog-project-hero h6{margin:3px 0;font-size:24px}.catalog-provider{color:#a5b4fc;font-size:11px;letter-spacing:.12em;text-transform:uppercase}.catalog-project-id,.catalog-result-meta{color:rgba(255,255,255,.4);font-size:11px}.catalog-description{color:rgba(255,255,255,.72);white-space:pre-wrap}.catalog-authors{color:rgba(255,255,255,.55);font-size:12px;margin-bottom:12px}.catalog-body{padding:14px;border-radius:10px;background:rgba(255,255,255,.045);color:rgba(255,255,255,.7);white-space:pre-wrap;max-height:240px;overflow:auto;margin-bottom:14px}.catalog-result-icon{background:rgba(255,255,255,.07)}
</style>
